import { getDiscussionQueryOptions } from './get-discussion';
import { getDiscussionsQueryOptions } from './get-discussions';

export const updateDiscussionPinned = ({
  discussionId,
  pinned,
}: {
  discussionId: string;
  pinned: boolean;
}) => {
  return api.patch(`/discussions/${discussionId}/pinned`, { pinned });
};

type UseUpdateDiscussionPinnedOptions = {
  mutationConfig?: MutationConfig<typeof updateDiscussionPinned>;
};

export const useUpdateDiscussionPinned = ({
  mutationConfig,
}: UseUpdateDiscussionPinnedOptions = {}) => {
  const queryClient = useQueryClient();
  const { addNotification } = useNotifications();

  const { onSuccess, ...restConfig } = mutationConfig || {};

  return useMutation({
    onSuccess: (data, variables, ...args) => {
      queryClient.refetchQueries({
        queryKey: getDiscussionQueryOptions(data.id).queryKey,
      });
      queryClient.invalidateQueries({
        queryKey: getDiscussionsQueryOptions().queryKey,
      });
      addNotification({
        type: 'success',
        title: variables.pinned
          ? 'Discussion pinned'
          : 'Discussion unpinned',
      });
      onSuccess?.(data, variables, ...args);
    },
    ...restConfig,
    mutationFn: updateDiscussionPinned,
  });
};

import { Pin, PinOff } from 'lucide-react';

import { MDPreview } from '@/components/ui/md-preview';
import { Spinner } from '@/components/ui/spinner';
import { paths } from '@/config/paths';
import { formatDate } from '@/utils/format';

import { useDiscussion } from '../api/get-discussion';
import { UpdateDiscussion } from '../components/update-discussion';

import { useUpdateDiscussionPinned } from '../api/update-discussion-pinned';
import { Authorization, ROLES } from '@/lib/authorization';
import { Button } from '@/components/ui/button';

export const DiscussionView = ({ discussionId }: { discussionId: string }) => {
  const discussionQuery = useDiscussion({
    discussionId,
  });

  if (discussionQuery.isLoading) {
    return (
      <div className="flex h-48 w-full items-center justify-center">
        <Spinner size="lg" />
      </div>
    );
  }

  const discussion = discussionQuery?.data?.data;

  if (!discussion) return null;

  return (
    <div>
      <span className="text-xs font-bold">
        {formatDate(discussion.createdAt)}
      </span>
      {discussion.author && (
        <span className="ml-2 text-sm font-bold">
          by {discussion.author.firstName} {discussion.author.lastName}
        </span>
      )}
      <div className="mt-6 flex flex-col space-y-16">
        <div className="flex justify-end">
          <UpdateDiscussion discussionId={discussionId} />
        </div>
        <div>
          <div className="overflow-hidden bg-white shadow sm:rounded-lg">
            <div className="px-4 py-5 sm:px-6">
              <div className="mt-1 max-w-2xl text-sm text-gray-500">
                <MDPreview value={discussion.body} />
              </div>
            </div>
          </div>
        </div>
      </div>
      <div className="mt-4 flex justify-end">
        <Authorization allowedRoles={[ROLES.ADMIN]}>
          <PinDiscussionToggle discussionId={discussionId} pinned={discussion.pinned} />
        </Authorization>
      </div>
    </div>
  );
};

const PinDiscussionToggle = ({
  discussionId,
  pinned,
}: {
  discussionId: string;
  pinned: boolean;
}) => {
  const pinMutation = useUpdateDiscussionPinned({});

  return (
    <Button
      variant="outline"
      size="sm"
      isLoading={pinMutation.isPending}
      onClick={() =>
        pinMutation.mutate({ discussionId, pinned: !pinned })
      }
      icon={pinned ? <PinOff className="size-4" /> : <Pin className="size-4" />}
    >
      {pinned ? 'Unpin' : 'Pin'}
    </Button>
  );
};
